import React, { useEffect, useState } from "react";
import { LayoutProps, Company } from "../interfaces";
import Navigation from "./nav";
import LanguageSelector from "./languageSelector";
import MainLogo from "./mainLogo";
import { useTranslation } from "gatsby-plugin-react-i18next";
import data from "../data/data.json";
import { BiLogoInstagramAlt } from "react-icons/bi";
import {
  FaSquareFacebook,
  FaSquareWhatsapp,
  FaSquarePhone,
  FaLinkedin,
} from "react-icons/fa6";
import AppLink from "./AppLink";
import CookieBanner from "./CookieBanner";
import {
  getCookieConsentState,
  setCookieConsentState,
  type CookieConsentState,
} from "../utils/cookieConsent";
import {
  disableAnalytics,
  initializeAnalytics,
  trackPageView,
} from "../utils/analytics";

const info: Company = data[0];

const Layout: React.FC<LayoutProps> = ({ children, data }) => {
  const { t } = useTranslation();
  const [consentState, setConsentState] = useState<CookieConsentState>("unset");
  const [isCookieBannerOpen, setIsCookieBannerOpen] = useState(false);

  function formatPhoneNumber(phoneNumber: string) {
    const cleaned = ("" + phoneNumber).replace(/\D/g, "");
    const match = cleaned.match(/^(?:\+1)?(\d{11})$/);
    if (match) {
      const digits = match[1];
      return `+1 (${digits.slice(1, 4)}) ${digits.slice(4, 7)}-${digits.slice(
        7,
        11
      )}`;
    }
    return phoneNumber;
  }

  const [currentYear, setYear] = React.useState<number | null>(null);

  React.useEffect(() => {
    setYear(new Date().getFullYear());
  }, []);

  useEffect(() => {
    const savedConsent = getCookieConsentState();
    setConsentState(savedConsent);
    setIsCookieBannerOpen(savedConsent === "unset");

    if (savedConsent !== "accepted") {
      disableAnalytics();
    }
  }, []);

  const handleAcceptCookies = async () => {
    setCookieConsentState("accepted");
    setConsentState("accepted");
    setIsCookieBannerOpen(false);
    await initializeAnalytics();
    await trackPageView();
  };

  const handleRejectCookies = () => {
    setCookieConsentState("rejected");
    setConsentState("rejected");
    setIsCookieBannerOpen(false);
    disableAnalytics();
  };

  return (
    <>
      {data && (
        <>
          <div className={styles.wrapper}>
            <div className={styles.header}>
              <div className={styles.logoContainer}>
                <MainLogo fillColour="#FCFCFC" />
              </div>
              <div className={styles.navbar}>
                <Navigation data={data} />
              </div>
              <div>
                <LanguageSelector />
              </div>
            </div>
            <div className={styles.childrenContent}>
              <main>{children}</main>
            </div>
          </div>
          <CookieBanner
            isOpen={isCookieBannerOpen}
            onAccept={() => {
              void handleAcceptCookies();
            }}
            onReject={handleRejectCookies}
          />
          <footer
            className="flex flex-col sm:flex-row bg-dark p-2 sm:p-0"
            id={info?.menu[3]}
          >
            <div className="flex w-full sm:w-1/3 h-12 sm:h-32 px-32 py-8">
              <MainLogo fillColour="#FCFCFC" />
            </div>
            <div className="flex flex-col w-full sm:w-1/3 text-light text-center self-center">
              <div className="w-full">
                {info.address}, {info.city}, {info.province}, {info.country}
              </div>
              <div className="w-full">
                <a
                  href={`tel:${info.phone}`}
                  className="flex flex-row gap-2 justify-center items-center text-lg font-bold"
                >
                  <FaSquarePhone />
                  {formatPhoneNumber(info.phone)}
                </a>
              </div>
              <div className="w-full">
                &copy; {currentYear} {info.companyName}
              </div>
              <div className="mt-3 flex items-center justify-center gap-4 text-sm">
                <AppLink
                  to="/privacy/"
                  className="underline underline-offset-4 hover:text-white"
                >
                  {t("footer.privacy")}
                </AppLink>
                <button
                  className="underline underline-offset-4 hover:text-white"
                  onClick={() => setIsCookieBannerOpen(true)}
                  type="button"
                >
                  {consentState === "unset"
                    ? t("footer.cookieChoices")
                    : t("footer.manageCookies")}
                </button>
              </div>
            </div>
            <div className="flex flex-row w-24 sm:w-1/3 text-light self-center justify-center -order-2 sm:order-1">
              <a
                href={info.instagram}
                className={styles.social}
                target="_blank"
                rel="noreferrer"
              >
                <BiLogoInstagramAlt className="w-12 h-12" />
                <span className="text-xs">Instagram</span>
              </a>
              <a href={info.facebook} className={styles.social} target="_blank" rel="noreferrer">
                <FaSquareFacebook className="w-12 h-12" />
                <span className="text-xs">Facebook</span>
              </a>
              <a href={info.whatsapp} className={styles.social} target="_blank" rel="noreferrer">
                <FaSquareWhatsapp className="w-12 h-12" />
                <span className="text-xs">Whatsapp</span>
              </a>
              <a href={info.linkedin} className={styles.social} target="_blank" rel="noreferrer">
                <FaLinkedin className="w-12 h-12" />
                <span className="text-xs">Linkedin</span>
              </a>
            </div>
          </footer>
        </>
      )}
    </>
  );
};

export default Layout;

const styles = {
  wrapper: "flex flex-col min-h-screen px-4 sm:px-0",
  header: "grid grid-flow-col justify-stretch items-center",
  logoContainer: "flex h-32 sm:h-60 w-32 sm:w-60 mx-auto pt-8",
  navbar: "flex w-1/2",
  childrenContent: "text-light",
  social: "flex flex-col items-center justify-center mx-4",
};
