import React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import AppLink from "./AppLink";

type CookieBannerProps = {
  isOpen: boolean;
  onAccept: () => void;
  onReject: () => void;
};

const CookieBanner: React.FC<CookieBannerProps> = ({
  isOpen,
  onAccept,
  onReject,
}) => {
  const { t } = useTranslation();

  if (!isOpen) {
    return null;
  }

  return (
    <div className="fixed inset-0 z-[70] flex items-end justify-center bg-dark/90 p-4">
      <section
        aria-labelledby="cookie-banner-title"
        aria-modal="true"
        className="w-full max-w-3xl rounded-2xl border-2 border-light gradient p-5 shadow-lg"
        role="dialog"
      >
        <div className="space-y-3 text-light">
          <p className="text-xs uppercase tracking-[0.16em] text-purplelight">
            {t("cookieBanner.eyebrow")}
          </p>
          <h2
            className="text-2xl sm:text-3xl poppins-bold text-light"
            id="cookie-banner-title"
          >
            {t("cookieBanner.title")}
          </h2>
          <p className="text-sm sm:text-base text-light/85">
            {t("cookieBanner.description")}
          </p>
          <ul className="space-y-2 text-sm text-light/80">
            <li>{t("cookieBanner.essential")}</li>
            <li>{t("cookieBanner.analytics")}</li>
            <li>{t("cookieBanner.controls")}</li>
          </ul>
        </div>

        <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex flex-wrap items-center gap-4 text-sm text-light/75">
            <AppLink
              to="/privacy/"
              className="underline underline-offset-4 hover:text-white"
            >
              {t("cookieBanner.privacyLink")}
            </AppLink>
          </div>

          <div className="flex flex-col gap-3 sm:flex-row">
            <button
              className="rounded-full border border-light bg-dark px-5 py-2 text-light transition hover:bg-white/10"
              onClick={onReject}
              type="button"
            >
              {t("cookieBanner.reject")}
            </button>
            <button
              className="rounded-full border border-light bg-light px-5 py-2 text-dark transition hover:opacity-90"
              onClick={onAccept}
              type="button"
            >
              {t("cookieBanner.accept")}
            </button>
          </div>
        </div>
      </section>
    </div>
  );
};

export default CookieBanner;
