// src/components/nav.tsx
import React, { useEffect, useMemo, useState } from "react";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import Link from "../components/AppLink";

import { FiMenu, FiX, FiChevronDown } from "react-icons/fi";
import { FaArrowUp } from "react-icons/fa";

interface NavProps {
  data?: {
    menu?: string[];
    whatsapp?: string;
  };
}

type ServiceLink = {
  labelKey: string; // i18n key
  to: string; // localized by Link
};

type IndustryLink = {
  labelKey: string;
  to: string;
};

function normalizePath(path?: string) {
  if (!path) return "/";
  if (path === "/") return "/";
  return path.endsWith("/") ? path : `${path}/`;
}

function isActivePath(
  currentPath: string,
  targetPath: string,
  partiallyActive = false
) {
  const current = normalizePath(currentPath);
  const target = normalizePath(targetPath);

  if (target === "/") {
    return current === "/";
  }

  return partiallyActive ? current.startsWith(target) : current === target;
}

function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ");
}

const Navigation: React.FC<NavProps> = ({ data }) => {
  const { t } = useTranslation();
  const { originalPath } = useI18next();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [showBackToTop, setShowBackToTop] = useState(false);

  // Desktop dropdown open/close + Mobile accordion open/close
  const [servicesOpenDesktop, setServicesOpenDesktop] = useState(false);
  const [servicesOpenMobile, setServicesOpenMobile] = useState(false);
  const [industriesOpenDesktop, setIndustriesOpenDesktop] = useState(false);
  const [industriesOpenMobile, setIndustriesOpenMobile] = useState(false);

  const servicesLinks: ServiceLink[] = useMemo(
    () => [
      {
        labelKey: "menu.services.webDesignDevelopment.nav",
        to: "/services/web-design-development/",
      },
      { labelKey: "menu.services.seo.nav", to: "/services/seo/" },
      {
        labelKey: "menu.services.aiSearchOptimization.nav",
        to: "/services/ai-search-optimization/",
      },
      {
        labelKey: "menu.services.maintenance.nav",
        to: "/services/maintenance/",
      },
      { labelKey: "menu.services.analytics.nav", to: "/services/analytics/" },
      // Optional:
      { labelKey: "menu.servicesHub.subnav", to: "/services/" },
    ],
    []
  );

  const industriesLinks: IndustryLink[] = useMemo(
    () => [
      { labelKey: "menu.industries.contractors.nav", to: "/contractors/" },
      { labelKey: "menu.industries.hospitality.nav", to: "/hospitality/" },
      {
        labelKey: "menu.industries.clinicsWellness.nav",
        to: "/clinics-wellness/",
      },
      {
        labelKey: "menu.industries.professionalServices.nav",
        to: "/professional-services/",
      },
    ],
    []
  );

  const toggleMenu = () => {
    setIsMenuOpen((v) => !v);
    // reset mobile accordion when closing
    if (isMenuOpen) {
      setServicesOpenMobile(false);
      setIndustriesOpenMobile(false);
    }
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: "smooth" });

  useEffect(() => {
    const handleScroll = () => setShowBackToTop(window.scrollY > 100);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Close dropdown when clicking outside (desktop)
  useEffect(() => {
    const onDocClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;
      if (target.closest?.("[data-services-dropdown]")) return;
      if (target.closest?.("[data-industries-dropdown]")) return;
      setServicesOpenDesktop(false);
      setIndustriesOpenDesktop(false);
    };
    document.addEventListener("click", onDocClick);
    return () => document.removeEventListener("click", onDocClick);
  }, []);

  const ctaHref = data?.whatsapp || "mailto:juanpablo@riano.ca";
  const ctaLabel = t("menu.nav.cta"); // "Book a call" / "Réserver un appel" / "Agendar una llamada"
  const currentPath = normalizePath(originalPath);
  const isServicesActive = isActivePath(currentPath, "/services/", true);
  const isIndustriesActive = industriesLinks.some((industry) =>
    isActivePath(currentPath, industry.to, true)
  );
  const isPortfolioActive = isActivePath(currentPath, "/portfolio/", true);
  const isBlogActive = isActivePath(currentPath, "/blog/", true);

  return (
    <nav className={styles.container} aria-label="Primary navigation">
      {/* MOBILE burger */}
      <button
        onClick={toggleMenu}
        className={styles.burgerButton}
        aria-label="Menu"
      >
        {isMenuOpen ? (
          <FiX className="text-white fixed right-4 z-[70] top-4" size={36} />
        ) : (
          <FiMenu className="text-white text-orange mx-8" size={36} />
        )}
      </button>

      {/* DESKTOP NAV */}
      <div className={styles.desktopWrapper}>
        <ul className={styles.desktopList}>
          <li className={styles.item}>
            <Link
              to="/"
              className={cn(
                styles.link,
                isActivePath(currentPath, "/") && styles.linkActive
              )}
              aria-current={isActivePath(currentPath, "/") ? "page" : undefined}
            >
              {t("menu.home")}
            </Link>
          </li>

          {/* Services dropdown */}
          <li className={`${styles.item} relative`} data-services-dropdown>
            <button
              className={cn(
                styles.dropdownButton,
                isServicesActive && styles.parentActive
              )}
              onClick={() => {
                setServicesOpenDesktop((v) => !v);
                setIndustriesOpenDesktop(false);
              }}
              aria-haspopup="menu"
              aria-expanded={servicesOpenDesktop}
            >
              {t("menu.servicesHub.nav")}
              <FiChevronDown className="ml-2" />
            </button>

            {servicesOpenDesktop ? (
              <div
                className={styles.dropdownPanel}
                role="menu"
                aria-label={t("menu.services") || "Services"}
              >
                <ul className="flex flex-col gap-1">
                  {/* First 5 = direct services */}
                  {servicesLinks.slice(0, 5).map((s) => (
                    <li key={s.to}>
                      {(() => {
                        const isActive = isActivePath(currentPath, s.to);
                        return (
                      <Link
                        to={s.to}
                        className={cn(
                          styles.dropdownLink,
                          isActive && styles.dropdownLinkActive
                        )}
                        onClick={() => setServicesOpenDesktop(false)}
                        aria-current={isActive ? "page" : undefined}
                      >
                        {t(s.labelKey)}
                      </Link>
                        );
                      })()}
                    </li>
                  ))}
                  {/* Optional "All services" */}
                  <li className="mt-2 pt-2 border-t border-black/10">
                    {(() => {
                      const isActive = isActivePath(currentPath, servicesLinks[5].to);
                      return (
                    <Link
                      to={servicesLinks[5].to}
                      className={cn(
                        styles.dropdownLinkMuted,
                        isActive && styles.dropdownLinkActive
                      )}
                      onClick={() => setServicesOpenDesktop(false)}
                      aria-current={isActive ? "page" : undefined}
                    >
                      {t(servicesLinks[5].labelKey)}
                    </Link>
                      );
                    })()}
                  </li>
                </ul>
              </div>
            ) : null}
          </li>

          <li className={`${styles.item} relative`} data-industries-dropdown>
            <button
              className={cn(
                styles.dropdownButton,
                isIndustriesActive && styles.parentActive
              )}
              onClick={() => {
                setIndustriesOpenDesktop((v) => !v);
                setServicesOpenDesktop(false);
              }}
              aria-haspopup="menu"
              aria-expanded={industriesOpenDesktop}
            >
              {t("menu.industriesHub.nav")}
              <FiChevronDown className="ml-2" />
            </button>

            {industriesOpenDesktop ? (
              <div
                className={styles.dropdownPanel}
                role="menu"
                aria-label={t("menu.industriesHub.nav") || "Industries"}
              >
                <ul className="flex flex-col gap-1">
                  {industriesLinks.map((industry) => (
                    <li key={industry.to}>
                      {(() => {
                        const isActive = isActivePath(
                          currentPath,
                          industry.to,
                          true
                        );
                        return (
                          <Link
                            to={industry.to}
                            className={cn(
                              styles.dropdownLink,
                              isActive && styles.dropdownLinkActive
                            )}
                            onClick={() => setIndustriesOpenDesktop(false)}
                            aria-current={isActive ? "page" : undefined}
                          >
                            {t(industry.labelKey)}
                          </Link>
                        );
                      })()}
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
          </li>

          <li className={styles.item}>
            <Link
              to="/portfolio"
              className={cn(styles.link, isPortfolioActive && styles.linkActive)}
              aria-current={isPortfolioActive ? "page" : undefined}
            >
              {t("menu.portfolio")}
            </Link>
          </li>

          <li className={styles.item}>
            <Link
              to="/about/"
              className={cn(
                styles.link,
                isActivePath(currentPath, "/about/", true) && styles.linkActive
              )}
              aria-current={isActivePath(currentPath, "/about/", true) ? "page" : undefined}
            >
              {t("menu.about")}
            </Link>
          </li>

          <li className={styles.item}>
            <Link
              to="/contact/"
              className={cn(
                styles.link,
                isActivePath(currentPath, "/contact/", true) && styles.linkActive
              )}
              aria-current={isActivePath(currentPath, "/contact/", true) ? "page" : undefined}
            >
              {t("menu.contact")}
            </Link>
          </li>

          <li className={styles.item}>
            <Link
              to="/blog"
              className={cn(styles.link, isBlogActive && styles.linkActive)}
              aria-current={isBlogActive ? "page" : undefined}
            >
              {t("menu.blog")}
            </Link>
          </li>
        </ul>

        <a
          href={ctaHref}
          target={ctaHref.startsWith("http") ? "_blank" : undefined}
          rel={ctaHref.startsWith("http") ? "noreferrer" : undefined}
          className={styles.ctaButton}
        >
          {ctaLabel}
        </a>
      </div>

      {/* MOBILE MENU PANEL */}
      <div
        className={`${styles.mobilePanel} ${
          isMenuOpen ? styles.menuOpen : styles.menuClosed
        }`}
        aria-hidden={!isMenuOpen}
      >
        <ul className="flex flex-col items-center gap-4">
          <li>
            <Link
              to="/"
              className={cn(
                styles.mobileLink,
                isActivePath(currentPath, "/") && styles.mobileLinkActive
              )}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
                setIndustriesOpenMobile(false);
              }}
              aria-current={isActivePath(currentPath, "/") ? "page" : undefined}
            >
              {t("menu.home")}
            </Link>
          </li>

          {/* Mobile Services accordion */}
          <li className="w-full max-w-md">
            <button
              className={cn(
                styles.mobileAccordionButton,
                isServicesActive && styles.mobileAccordionButtonActive
              )}
              onClick={() => {
                setServicesOpenMobile((v) => !v);
                setIndustriesOpenMobile(false);
              }}
              aria-expanded={servicesOpenMobile}
            >
              <span>{t("menu.servicesHub.subnav")}</span>
              <FiChevronDown
                className={`${
                  servicesOpenMobile ? "rotate-180" : ""
                } transition-transform`}
              />
            </button>

            {servicesOpenMobile ? (
              <div className={styles.mobileAccordionPanel}>
                <ul className="flex flex-col gap-2">
                  {servicesLinks.slice(0, 5).map((s) => (
                    <li key={s.to}>
                      {(() => {
                        const isActive = isActivePath(currentPath, s.to);
                        return (
                      <Link
                        to={s.to}
                        className={cn(
                          styles.mobileSubLink,
                          isActive && styles.mobileSubLinkActive
                        )}
                        onClick={() => {
                          setIsMenuOpen(false);
                          setServicesOpenMobile(false);
                          setIndustriesOpenMobile(false);
                        }}
                        aria-current={isActive ? "page" : undefined}
                      >
                        {t(s.labelKey)}
                      </Link>
                        );
                      })()}
                    </li>
                  ))}
                  <li className="pt-2 mt-2 border-t border-white/15">
                    {(() => {
                      const isActive = isActivePath(currentPath, servicesLinks[5].to);
                      return (
                    <Link
                      to={servicesLinks[5].to}
                      className={cn(
                        styles.mobileSubLinkMuted,
                        isActive && styles.mobileSubLinkActive
                      )}
                      onClick={() => {
                        setIsMenuOpen(false);
                        setServicesOpenMobile(false);
                        setIndustriesOpenMobile(false);
                      }}
                      aria-current={isActive ? "page" : undefined}
                    >
                      {t(servicesLinks[5].labelKey)}
                    </Link>
                      );
                    })()}
                  </li>
                </ul>
              </div>
            ) : null}
          </li>

          <li className="w-full max-w-md">
            <button
              className={cn(
                styles.mobileAccordionButton,
                isIndustriesActive && styles.mobileAccordionButtonActive
              )}
              onClick={() => {
                setIndustriesOpenMobile((v) => !v);
                setServicesOpenMobile(false);
              }}
              aria-expanded={industriesOpenMobile}
            >
              <span>{t("menu.industriesHub.subnav")}</span>
              <FiChevronDown
                className={`${
                  industriesOpenMobile ? "rotate-180" : ""
                } transition-transform`}
              />
            </button>

            {industriesOpenMobile ? (
              <div className={styles.mobileAccordionPanel}>
                <ul className="flex flex-col gap-2">
                  {industriesLinks.map((industry) => (
                    <li key={industry.to}>
                      {(() => {
                        const isActive = isActivePath(
                          currentPath,
                          industry.to,
                          true
                        );
                        return (
                          <Link
                            to={industry.to}
                            className={cn(
                              styles.mobileSubLink,
                              isActive && styles.mobileSubLinkActive
                            )}
                            onClick={() => {
                              setIsMenuOpen(false);
                              setServicesOpenMobile(false);
                              setIndustriesOpenMobile(false);
                            }}
                            aria-current={isActive ? "page" : undefined}
                          >
                            {t(industry.labelKey)}
                          </Link>
                        );
                      })()}
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
          </li>

          <li>
            <Link
              to="/portfolio"
              className={cn(
                styles.mobileLink,
                isPortfolioActive && styles.mobileLinkActive
              )}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
                setIndustriesOpenMobile(false);
              }}
              aria-current={isPortfolioActive ? "page" : undefined}
            >
              {t("menu.portfolio")}
            </Link>
          </li>

          <li>
            <Link
              to="/about/"
              className={cn(
                styles.mobileLink,
                isActivePath(currentPath, "/about/", true) && styles.mobileLinkActive
              )}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
                setIndustriesOpenMobile(false);
              }}
              aria-current={isActivePath(currentPath, "/about/", true) ? "page" : undefined}
            >
              {t("menu.about")}
            </Link>
          </li>

          <li>
            <Link
              to="/contact/"
              className={cn(
                styles.mobileLink,
                isActivePath(currentPath, "/contact/", true) &&
                  styles.mobileLinkActive
              )}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
                setIndustriesOpenMobile(false);
              }}
              aria-current={
                isActivePath(currentPath, "/contact/", true) ? "page" : undefined
              }
            >
              {t("menu.contact")}
            </Link>
          </li>

          <li>
            <Link
              to="/blog"
              className={cn(styles.mobileLink, isBlogActive && styles.mobileLinkActive)}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
                setIndustriesOpenMobile(false);
              }}
              aria-current={isBlogActive ? "page" : undefined}
            >
              {t("menu.blog")}
            </Link>
          </li>

          <li className="mt-2">
            <a
              href={ctaHref}
              target={ctaHref.startsWith("http") ? "_blank" : undefined}
              rel={ctaHref.startsWith("http") ? "noreferrer" : undefined}
              className={styles.mobileCta}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
                setIndustriesOpenMobile(false);
              }}
            >
              {ctaLabel}
            </a>
          </li>
        </ul>
      </div>

      {showBackToTop ? (
        <button
          onClick={scrollToTop}
          className={styles.backToTopButton}
          aria-label="Back to top"
        >
          <FaArrowUp size={20} />
        </button>
      ) : null}
    </nav>
  );
};

export default Navigation;

const styles = {
  container:
    "relative z-10 mx-0 sm:mx-8 px-4 py-2 rounded-none sm:rounded-full bg-transparent sm:bg-secondary",

  // Mobile
  burgerButton: "md:hidden block focus:outline-none mx-auto",
  mobilePanel:
    "md:hidden fixed left-0 top-0 w-full h-full bg-secondary pt-20 pb-10 px-6 overflow-y-auto",
  mobileLink:
    "text-white text-2xl px-4 py-0 hover:underline hover:text-purplelight text-nowrap",
  mobileLinkActive:
    "rounded-full bg-white/10 px-4 py-2 text-verde no-underline hover:text-verde",
  mobileAccordionButton:
    "w-full flex items-center justify-between px-4 py-3 rounded-xl border border-white/10 bg-white/5 text-white text-xl",
  mobileAccordionButtonActive: "border-verde bg-white/10 text-verde",
  mobileAccordionPanel: "mt-2 px-2",
  mobileSubLink:
    "block w-full px-4 py-2 rounded-lg text-white/90 hover:bg-white/10",
  mobileSubLinkActive: "bg-white/10 font-semibold text-verde",
  mobileSubLinkMuted:
    "block w-full px-4 py-2 rounded-lg text-white/70 hover:bg-white/10",
  mobileCta:
    "inline-flex rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center",

  // Desktop
  desktopWrapper: "hidden md:flex items-center justify-between gap-6",
  desktopList: "flex items-center gap-2",
  item: "my-0",
  link: "text-white text-base px-3 py-2 hover:underline hover:text-purplelight text-nowrap",
  linkActive:
    "rounded-full bg-white/10 font-semibold text-verde no-underline hover:text-verde",
  dropdownButton:
    "text-white text-base px-3 py-2 hover:underline hover:text-purplelight text-nowrap inline-flex items-center",
  parentActive:
    "rounded-full bg-white/10 font-semibold text-verde no-underline hover:text-verde",
  dropdownPanel:
    "absolute left-0 mt-2 w-80 rounded-2xl border border-black/10 bg-white/80 p-3 shadow-lg supports-[backdrop-filter]:bg-white/50 supports-[backdrop-filter]:backdrop-blur",
  dropdownLink:
    "block w-full rounded-xl px-3 py-2 text-sm text-black/85 hover:bg-black/5",
  dropdownLinkActive: "bg-black/10 font-semibold text-black",
  dropdownLinkMuted:
    "block w-full rounded-xl px-3 py-2 text-sm text-black/65 hover:bg-black/5",

  ctaButton:
    "hidden md:inline-flex rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center whitespace-nowrap",

  // Shared
  menuOpen: "block",
  menuClosed: "hidden",

  backToTopButton:
    "fixed bottom-4 right-4 bg-secondary text-white p-2 rounded-full shadow-lg z-50",
};
